  // Show the source of a statement in a dialog, like the information buttons of the rating app
  (function () {
    const backdrop = document.getElementById("source-backdrop");
    const closeButton = document.getElementById("source-dialog-close");
    let opener = null;

    const open = (button) =&gt; {
      const source = button.dataset.source;
      const split = source.lastIndexOf(", p");
      document.getElementById("source-dialog-document").textContent = split &gt; 0 ? source.slice(0, split) : source;
      document.getElementById("source-dialog-page").textContent =
        split &gt; 0 ? source.slice(split + 2).replace(/^pp?\.\s*/, "") : "–";
      opener = button;
      backdrop.hidden = false;
      closeButton.focus();
    };
    const close = () =&gt; {
      if (backdrop.hidden) return;
      backdrop.hidden = true;
      if (opener) opener.focus();
    };

    document.addEventListener("click", (event) =&gt; {
      const button = event.target.closest(".source-ref");
      if (button) open(button);
    });
    closeButton.addEventListener("click", close);
    backdrop.addEventListener("click", (event) =&gt; {
      if (event.target === backdrop) close();
    });
    document.addEventListener("keydown", (event) =&gt; {
      if (event.key === "Escape") close();
    });
  })();
